const currentYear = document.getElementById("currentYear"); if (currentYear) { currentYear.textContent = new Date().getFullYear(); }  const navigationLinks = document.querySelectorAll( '#mainNavigation a.nav-link:not([data-bs-toggle="dropdown"]), #mainNavigation a.dropdown-item' ); const navigationMenu = document.getElementById("mainNavigation"); navigationLinks.forEach(function (link) { link.addEventListener("click", function () {  if ( window.innerWidth < 992 && navigationMenu && typeof bootstrap !== "undefined" && navigationMenu.classList.contains("show") ) { const bootstrapCollapse = bootstrap.Collapse.getInstance(navigationMenu); if (bootstrapCollapse) { bootstrapCollapse.hide(); } } }); }); const frameworkQuiz = document.getElementById("frameworkQuiz"); if (frameworkQuiz) { frameworkQuiz.addEventListener("submit", function (event) { event.preventDefault(); const projectType = document.getElementById("projectType").value; const priority = document.getElementById("priority").value; const result = document.getElementById("quizResult"); let framework = ""; let description = ""; if (projectType === "website" || priority === "full") { framework = "Django"; description = "Django хорошо подходит для полноценных веб-приложений " + "с пользователями, базой данных, административной панелью " + "и большим количеством готовых компонентов."; } else if (projectType === "api" || priority === "speed") { framework = "FastAPI"; description = "FastAPI особенно хорошо подходит для API, backend-сервисов " + "и приложений, где важны асинхронность и производительность."; } else { framework = "Flask"; description = "Flask подойдёт для небольших приложений и проектов, " + "где важны простота и свобода выбора архитектуры."; } result.innerHTML = "<strong>Мы рекомендуем: " + framework + "</strong><br>" + description; result.classList.remove("d-none"); }); }
